1	"use strict";
2	const $ = (id) => document.getElementById(id);
3	const el = (tag, text) => {
4	  const n = document.createElement(tag);
5	  if (text !== undefined) n.textContent = text;
6	  return n;
7	};
8	const state = {
9	  session: 0,
10	  eventsGeneration: 0,
11	  token: "",
12	  config: null,
13	  dirty: false,
14	  before: "",
15	  offset: 0,
16	  more: false,
17	  review: null,
18	  detailGeneration: 0,
19	  timer: null,
20	};
21	const json = (value) => JSON.stringify(value, null, 2);
22	const stamp = (value) =>
23	  value ? new Date(value).toLocaleString() : "Not observed";
24	function notice(text) {
25	  $("notice").textContent = text;
26	}
27	async function api(path, body) {
28	  const session = state.session;
29	  const controller = new AbortController(),
30	    timer = setTimeout(
31	      () => controller.abort(),
32	      path.endsWith("/activate")
33	        ? 180000
34	        : path.endsWith("/test-model")
35	          ? 45000
36	          : 20000,
37	    );
38	  try {
39	    const response = await fetch(path, {
40	      method: body === undefined ? "GET" : "POST",
41	      cache: "no-store",
42	      signal: controller.signal,
43	      headers: {
44	        Authorization: `Bearer ${state.token}`,
45	        ...(body === undefined
46	          ? {}
47	          : { "Content-Type": "application/json", "X-Mrmr-Control": "1" }),
48	      },
49	      body: body === undefined ? undefined : JSON.stringify(body),
50	    });
51	    if (session !== state.session) throw Error("Management session changed.");
52	    if (response.status === 401) {
53	      lock();
54	      throw Error("Operator token rejected. Unlock again.");
55	    }
56	    if (!response.ok) throw Error((await response.text()).slice(0, 1000));
57	    const value = await response.json();
58	    if (session !== state.session) throw Error("Management session changed.");
59	    return value;
60	  } finally {
61	    clearTimeout(timer);
62	  }
63	}
64	function action(id, fn) {
65	  $(id).addEventListener("click", async (e) => {
66	    e.preventDefault();
67	    const b = e.currentTarget;
68	    b.disabled = true;
69	    try {
70	      await fn();
71	    } catch (err) {
72	      notice(
73	        err.name === "AbortError"
74	          ? "Request timed out. Refresh runtime state before retrying a change."
75	          : err.message,
76	      );
77	    } finally {
78	      b.disabled = false;
79	      if (id === "setup-start") refreshSetupStart();
80	    }
81	  });
82	}
83	function lock() {
84	  state.session++;
85	  state.token = "";
86	  state.detailGeneration++;
87	  clearTimeout(state.timer);
88	  $("app").hidden = true;
89	  $("login").hidden = false;
90	  $("logout").hidden = true;
91	  $("token").value = "";
92	  $("yaml").value = "";
93	  $("review-id").value = "";
94	  $("host").textContent = "Management";
95	  state.config = null;
96	  state.review = null;
97	  state.dirty = false;
98	  for (const id of [
99	    "model-form",
100	    "source-form",
101	    "policy-form",
102	    "review-form",
103	    "search",
104	  ])
105	    $(id).reset();
106	  for (const id of [
107	    "events",
108	    "event-detail",
109	    "review-evidence",
110	    "review-history",
111	    "audit",
112	    "evaluations",
113	    "revisions",
114	    "diff-content",
115	    "configured-sources",
116	    "configured-models",
117	    "configured-rules",
118	    "interpreter-model",
119	    "connections",
120	    "source-health",
121	    "model-health",
122	    "overview-content",
123	    "active-monitors",
124	  ])
125	    $(id).replaceChildren();
126	  resetSetup();
127	  notice("Management locked.");
128	}
129	function page() {
130	  const requested = location.hash.slice(1);
131	  const name = [
132	    "overview",
133	    "activity",
134	    "review",
135	    "configure",
136	    "runtime",
137	  ].includes(requested)
138	    ? requested
139	    : "overview";
140	  for (const section of document.querySelectorAll("[data-page]"))
141	    section.hidden = section.dataset.page !== name;
142	  for (const a of document.querySelectorAll("nav a")) {
143	    if (a.hash === `#${name}`) a.setAttribute("aria-current", "page");
144	    else a.removeAttribute("aria-current");
145	  }
146	  document.title = `mrmr · ${name}`;
147	}
148	window.addEventListener("hashchange", page);
149	page();
150	$("login-form").addEventListener("submit", async (e) => {
151	  e.preventDefault();
152	  state.session++;
153	  state.token = REDACTED;
154	  $("token").value = "";
155	  try {
156	    await loadConfig();
157	    $("login").hidden = true;
158	    $("app").hidden = false;
159	    $("logout").hidden = false;
160	    await overview();
161	    await events();
162	    const id = new URLSearchParams(location.search).get("event");
163	    if (id) await detail(id);
164	    notice("Operator access active. Changes are recorded.");
165	  } catch (err) {
166	    notice(err.message);
167	  }
168	});
169	$("logout").addEventListener("click", lock);
170	function record(title, text) {
171	  const n = el("div");
172	  n.className = "record";
173	  n.append(el("h3", title), el("p", text));
174	  return n;
175	}
176	async function overview() {
177	  clearTimeout(state.timer);
178	  if (!state.token) return;
179	  try {
180	    if (!state.config || state.config.setup) {
181	      $("overview-content").replaceChildren(
182	        record(
183	          "Setup required",
184	          "Open Configure to set a model endpoint and source. Collection is disabled.",
185	        ),
186	      );
187	      return;
188	    }
189	    const data = await api("/dashboard/api/overview");
190	    $("host").textContent = data.hostname;
191	    $("freshness").textContent =
192	      `Runtime answered ${stamp(data.at)}. Source evidence resets when its runtime revision changes.`;
193	    const s = data.summary;
194	    $("overview-content").replaceChildren(
195	      record(
196	        "Stored evidence",
197	        `${s.events} events · ${s.unlabeled} unlabeled · ${s.pending} unfinished execution intents`,
198	      ),
199	    );
200	    const effects = data.policy.filter((r) => r.outcome !== "ignore"),
201	      live = effects.filter((r) => !r.shadow).length;
202	    $("overview-content").append(
203	      record(
204	        "Effect boundary",
205	        data.effects_blocked
206	          ? "Operator safety gate: effects blocked."
207	          : live
208	            ? `${live} configured live effect rule(s).`
209	            : "Configured effects are shadowed or ignored.",
210	      ),
211	    );
212	    const links = el("p");
213	    for (const [label, view] of [
214	      ["Inspect errors", "errors"],
215	      ["Review unlabeled events", "unlabeled"],
216	      ["Inspect unfinished intents", "pending"],
217	    ]) {
218	      const a = el("a", label);
219	      a.href = `?view=${view}#activity`;
220	      a.addEventListener("click", (e) => {
221	        if (e.ctrlKey || e.metaKey || e.shiftKey) return;
222	        e.preventDefault();
223	        $("view").value = view;
224	        $("query").value = "";
225	        state.before = "";
226	        state.offset = 0;
227	        location.hash = "activity";
228	        saveSearch();
229	        events().catch((e) => notice(e.message));
230	      });
231	      links.append(a, document.createTextNode(" · "));
232	    }
233	    $("overview-content").append(links);
234	    $("source-health").replaceChildren();
235	    for (const source of data.sources) {
236	      const h = source.health,
237	        finished = new Date(h.finished_at),
238	        limit = Math.max(30000, source.every_ms * 3);
239	      const status = source.paused
240	        ? "Paused; cursor retained"
241	        : h.failed
242	          ? "Last poll failed"
243	          : h.running
244	            ? "Poll in progress"
245	            : finished.getFullYear() > 1
246	              ? new Date(data.at) - finished > limit
247	                ? "No recent completed poll"
248	                : "Last poll completed; an empty poll is not a failure"
249	              : "First poll not observed";
250	      $("source-health").append(
251	        record(
252	          source.name,
253	          `${status}. ${source.type}; ${source.every_ms / 1000}s interval.`,
254	        ),
255	      );
256	    }
257	    if (!data.sources.length)
258	      $("source-health").append(
259	        el("p", "No pull sources configured. HTTP ingress remains available."),
260	      );
261	    $("model-health").replaceChildren();
262	    for (const m of s.models)
263	      $("model-health").append(
264	        record(
265	          m.interpreter,
266	          `${m.model} · ${m.successes}/${m.count} successful · median ${m.median_ms ?? "not measured"} ms · ${m.errors} errors. Latest decision ${stamp(m.last_at)}.`,
267	        ),
268	      );
269	  } catch (err) {
