# mrmr example configuration.
# Copy to mrmr.yaml and adjust. Secrets never live here: api_key_env names
# an environment variable that the runtime reads at request time.

server:
  addr: ":4242"

db:
  path: "mrmr.db"

# Deterministic checks before the model. All checks must pass; an event
# that fails any is recorded and ignored before interpretation. A field
# the event does not carry fails every check, so filter on fields your
# sources always send (source is always present).
filter:
  - field: source
    op: neq
    value: noise-bot

models:
  fast-local:
    role: decision
    # Legacy prompt/schema judgment remains supported. For typed questions and
    # a complete investigation loop, see recipes/homelab-ambient/.
    provider: openai-compatible
    base_url: http://localhost:8000/v1
    api_key_env: MRMR_MODEL_API_KEY
    model: llama-3.1-8b-instruct
  worker:
    role: agent
    provider: openai-compatible
    base_url: http://localhost:8081/v1
    model: LFM2.5-2.6B

interpret:
  model: fast-local
  prompt: |
    You classify ambient events for a home runtime. Given an event as JSON,
    judge what it means and return a structured decision.

    Rules of thumb:
    - incident: something is broken or failing right now.
    - noise: routine chatter that never needs attention.
    - FYI: interesting but nothing to do.
    - actionable: something the user should consider doing.
    - importance is 0.0 to 1.0.
    - requires_action is true only when the user genuinely needs to act.
    - summary is one short sentence.

  schema:
    category:
      type: string
      enum: [incident, noise, FYI, actionable]
    importance:
      type: number
      minimum: 0
      maximum: 1
    requires_action:
      type: boolean
    confidence:
      type: number
      minimum: 0
      maximum: 1
    summary:
      type: string

# Pull-based sources poll a JSON endpoint on an interval and feed each
# record through the same pipeline as POST /api/events. One goroutine per
# source; the cursor is persisted so restarts resume where they left off,
# and dedup on (source, source_event_id) means repolling is harmless.
