211	    outcome.append(node('span', `Decision: ${e.decision_status || 'not recorded'}${e.labeled ? ' · labeled' : ' · unlabeled'}`, `secondary ${['errored', 'invalid'].includes(e.decision_status) ? 'state error' : ''}`));
