217	  if (!page.events.length) emptyRow('events-body', 4, state.query || state.view !== 'all' ? 'No matching events. Change the search or filter.' : 'No events stored yet. Check the source scope and poll status.');
218	  $('event-status').textContent = 'Select an event to inspect its decision and trace.';
219	  $('page-label').textContent = page.events.length ? `${state.offset + 1}–${state.offset + page.events.length}` : 'No results';
