227	  const timeout = setTimeout(() => controller.abort(), 8000);
228	  $('refresh').disabled = true;
229	  try {
230	    const params = new URLSearchParams({q: state.query, view: state.view, offset: state.offset, before: state.before});
231	    const [overview, page] = await Promise.all([get('overview', controller.signal), get(`events?${params}`, controller.signal)]);
232	    if (state.controller !== controller) return;
233	    renderOverview(overview); renderEvents(page);
234	  } catch (error) {
235	    if (state.controller !== controller) return;
236	    $('connection').className = 'connection warning';
237	    $('connection').textContent = `Live data unavailable. ${error.name === 'AbortError' ? 'Request timed out.' : error.message} Last update: ${stamp(state.lastAt)}. Check the runtime and your private connection, then retry.`;
238	    $('event-status').textContent = 'Displayed events may be stale. Refresh now to retry.';
239	  } finally {
240	    clearTimeout(timeout);
241	    if (state.controller === controller) {
