251	async function openEvent(id, moveFocus = false) {
252	  state.selected = id; state.detailController?.abort();
253	  for (const button of $('events-body').querySelectorAll('.event-open')) {
254	    const selected = button.dataset.eventId === id;
255	    if (selected) button.setAttribute('aria-current', 'true'); else button.removeAttribute('aria-current');
256	    button.closest('tr').classList.toggle('selected', selected);
257	  }
258	  const controller = new AbortController(); state.detailController = controller;
259	  const timeout = setTimeout(() => controller.abort(), 8000);
260	  $('detail').hidden = false; $('detail-title').textContent = `Event ${id}`;
261	  $('detail-status').textContent = 'Loading stored records…'; $('detail-content').replaceChildren();
262	  if (moveFocus) { $('detail').focus(); $('detail').scrollIntoView({block: 'start'}); }
263	  try {
264	    const ins = await get(`event?id=${encodeURIComponent(id)}`, controller.signal);
265	    if (state.detailController !== controller) return;
266	    const root = $('detail-content'), e = ins.event;
267	    root.append(node('p', `${e.subject || e.type} · ${e.source} · event time ${stamp(e.timestamp)}`));
268	    root.append(node('h3', 'Recorded result'));
269	    if (ins.executions?.length) {
270	      for (const x of ins.executions) root.append(node('p', executionSummary(x)));
271	    } else {
272	      root.append(node('p', 'No execution recorded. The event may still be processing or its result may be unavailable.'));
273	    }
274	    const parent = e.provenance?.parent_event_id;
275	    if (parent || ins.child_event_ids?.length) {
276	      root.append(node('h3', 'Related events'));
277	      const links = node('ul');
278	      for (const [label, related] of [['Parent', parent], ...(ins.child_event_ids || []).map(child => ['Child', child])]) {
279	        if (!related) continue;
280	        const item = node('li'), link = node('a', `${label}: ${related}`);
281	        link.href = locationFor(related);
282	        link.addEventListener('click', event => {
