284	          event.preventDefault(); state.selected = related; navigate(); openEvent(related, true);
285	        });
286	        item.append(link); links.append(item);
287	      }
288	      root.append(links);
289	    }
290	    root.append(node('h3', 'Original message / event (redacted)'), node('pre', typeof e.data?.message === 'string' ? e.data.message : ins.event_json));
291	    // The server formats this before JSON numbers enter JavaScript's float64.
292	    const fullEvent = node('details');
293	    fullEvent.append(node('summary', 'Full normalized Event'), node('pre', ins.event_json));
294	    root.append(fullEvent);
295	    root.append(node('h3', 'Decision → outcome'));
296	    for (const d of ins.decisions || []) {
297	      root.append(node('p', `${d.interpreter} · ${d.model} · ${d.status} · ${ms(d.latency_ms)}`));
298	      root.append(node('pre', json(d.result || {error: d.error || 'No valid model result'})));
299	    }
300	    if (!ins.decisions?.length) root.append(node('p', 'No decision recorded. The event may be filtered, in flight, or incomplete.'));
301	    for (const x of ins.executions || []) {
302	      root.append(node('p', `${x.policy_rule || 'No policy reference'} → ${x.outcome} · ${x.status}${x.adapter ? ` · ${x.adapter}` : ''}`));
303	      if (x.policy_hash) root.append(node('p', `Recorded policy revision: ${x.policy_hash}. Its historical definition may not be available.`, 'help'));
304	      if (x.status === 'shadow') root.append(node('p', 'Recorded only. No adapter effect was performed.'));
305	      if (x.status === 'pending') root.append(node('p', 'Unfinished intent. This does not prove whether an effect happened.', 'warning'));
306	      if (x.error) root.append(node('pre', x.error));
307	    }
308	    if (!ins.executions?.length) root.append(node('p', 'No execution recorded. Refresh to check for completion.'));
309	    root.append(node('h3', 'Trace'));
310	    const trace = node('ol', undefined, 'trace');
311	    for (const step of ins.trace || []) {
312	      const item = node('li'); item.append(node('strong', step.stage), node('small', stamp(step.at)), node('span', step.msg)); trace.append(item);
313	    }
314	    root.append(trace);
315	    if (!ins.trace?.length) root.append(node('p', 'No completed trace recorded.'));
316	    root.append(details('Human label', ins.label || 'Unlabeled. Label through the CLI after review.'));
317	    $('detail-status').textContent = `Detail snapshot: ${new Date().toLocaleString()}. Refresh this event for later records.`;
318	  } catch (error) {
319	    if (state.detailController === controller) $('detail-status').textContent = `${error.name === 'AbortError' ? 'Request timed out.' : error.message} Use Refresh this event to retry.`;
320	  } finally { clearTimeout(timeout); }
