323	$('search-form').addEventListener('submit', e => { e.preventDefault(); search(); });
324	$('view').addEventListener('change', search);
325	$('previous').addEventListener('click', () => { state.offset = Math.max(0, state.offset - 50); closeDetail(false); navigate(); refresh(); });
326	$('next').addEventListener('click', () => { state.offset = Math.min(100000, state.offset + 50); closeDetail(false); navigate(); refresh(); });
327	$('refresh-detail').addEventListener('click', () => { if (state.selected) openEvent(state.selected); });
328	function closeDetail(moveFocus) {
329	  state.detailController?.abort(); state.detailController = null; $('detail').hidden = true;
330	  const button = [...$('events-body').querySelectorAll('.event-open')].find(el => el.dataset.eventId === state.selected);
331	  if (moveFocus) (button || $('query')).focus();
332	  state.selected = null;
333	  if (button) { button.removeAttribute('aria-current'); button.closest('tr').classList.remove('selected'); }
334	}
335	$('close-detail').addEventListener('click', () => { closeDetail(true); navigate(); });
336	// Back and Forward restore the same filter, page, and event without a reload.
337	window.addEventListener('popstate', () => {
338	  closeDetail(false);
339	  const id = readLocation();
340	  if (id) openEvent(id);
341	  refresh();
342	});
343	// The page owns polling. Hidden pages stop scheduling; returning always gets
344	// fresh evidence rather than leaving a green status from the previous visit.
345	document.addEventListener('visibilitychange', () => {
346	  clearTimeout(state.timer);
347	  if (!document.hidden) refresh();
