349	    // Invalidate pending responses too; they must not turn a paused view green.
350	    state.controller?.abort(); state.controller = null; $('refresh').disabled = false;
351	    $('connection').className = 'connection warning'; $('connection').textContent = 'Live refresh paused while this page is hidden.';
352	  }
353	});
354	window.addEventListener('pagehide', () => { clearTimeout(state.timer); state.controller?.abort(); state.detailController?.abort(); });
355	window.addEventListener('pageshow', e => { if (e.persisted) refresh(); });
356	const initialEvent = readLocation();
357	if (initialEvent) openEvent(initialEvent);
358	refresh();
