192	  .page-heading { align-items: start; flex-wrap: wrap; gap: 16px; }
193	  h1 { font-size: 2rem; }
194	  .section-heading { flex-wrap: wrap; gap: 5px; }
195	  .totals { gap: 10px 20px; }
196	  .totals-note { width: 100%; }
197	  aside { grid-template-columns: 1fr; gap: 24px; }
198	  .timeline-scroll { scrollbar-gutter: auto; max-height: 620px; }
199	  /* Reflow complete records on phones. Outcome and latency must not disappear
200	     beyond a horizontal scroll while only the message remains visible. */
201	  .events, .timings { min-width: 0; }
202	  .events thead, .timings thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
203	  .events tbody, .timings tbody { display: block; }
204	  .events tr { display: grid; grid-template-columns: minmax(0, 1fr) auto; padding: 14px 0; border-bottom: 1px solid var(--line); gap: 6px 12px; }
205	  .events td { padding: 0; border: 0; }
206	  .events td:first-child { grid-area: 1 / 1; width: auto; }
207	  .events td:nth-child(2) { grid-area: 2 / 1 / auto / 3; padding: 4px 0 8px; }
208	  .events td:nth-child(3) { grid-area: 3 / 1 / auto / 3; width: auto; }
209	  .events td:last-child:not(:first-child) { grid-area: 1 / 2; width: auto; font-size: .75rem; }
210	  .events .secondary { display: inline; margin-left: 8px; }
211	  .events td.empty { grid-column: 1 / -1; padding: 20px 10px; }
212	  .event-open { min-height: 36px; }
213	  .timings tr { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); padding: 12px 0; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
214	  .timings td { padding: 0; border: 0; }
215	  .timings td:first-child { grid-column: 1 / -1; max-width: none; min-width: 0; }
216	  .timings td:not(:first-child) { text-align: left; }
217	  .timings td[data-label]::before { content: attr(data-label); display: block; color: var(--muted); font-size: .6875rem; font-weight: 400; margin-bottom: 3px; }
218	  .detail { padding: 16px; }
219	  .detail .section-heading { flex-wrap: nowrap; }
220	  .pagination { gap: 8px; }
221	  .pagination button { padding: 8px 10px; }
222	}
