/* Page-specific layout for /manage/. Tokens, controls, lamps, tracks, and tables
   live in signal.css so this page and the read-only dashboard stay one system. */

/* Sections and navigation mean nothing before unlock, and links to them would
   lead nowhere: the app is hidden until a token is accepted. */
body.locked .topbar nav {
  display: none;
}
#login {
  max-width: 520px;
  margin: 8vh auto 0;
  padding: 24px;
}
#login h1 {
  margin-bottom: 10px;
  font-size: 1.6rem;
}
#login form {
  margin: 16px 0;
}
#login button {
  margin-top: 12px;
}
#login input {
  width: 100%;
}
#login .help {
  margin: 0;
}

/* A floating result stays visible from the bottom of a long editor. It sits at
   the bottom edge so it never covers a focused field scrolled to the top. */
#notice-bar {
  position: fixed;
  z-index: 4;
  left: 50%;
  bottom: 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  width: min(640px, calc(100vw - 32px));
  padding: 8px 8px 8px 16px;
  border-radius: 8px;
  background: var(--graphite);
  color: #fff;
  box-shadow: 0 6px 20px rgb(32 36 42 / 28%);
  transform: translateX(-50%);
}
#notice-bar[data-tone="error"] {
  background: var(--stop-ink);
}
#notice {
  flex: 1;
  margin: 0;
  max-height: 30vh;
  overflow: auto;
  font-size: 0.875rem;
  overflow-wrap: anywhere;
}
#notice-close {
  color: #fff;
  flex: none;
}
#notice-close:hover {
  background: rgb(255 255 255 / 15%);
  color: #fff;
}
#notice-bar :focus-visible {
  outline-color: #fff;
}

label {
  display: block;
  margin: 12px 0 5px;
  font-size: 0.8125rem;
  font-weight: 600;
}
input:not([type="checkbox"]),
textarea {
  width: 100%;
}
textarea {
  display: block;
  min-height: 420px;
  resize: vertical;
  font-size: 0.8125rem;
  line-height: 1.6;
}
form {
  margin: 0;
}
details {
  margin: 12px 0;
}
details > summary {
  padding: 6px 0;
}
.row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.row input {
  flex: 1;
  min-width: 160px;
  width: auto;
}
.fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px 20px;
  margin: 12px 0 16px;
}
.fields label {
  margin: 0;
}
.fields input,
.fields select,
#setup-form label > select {
  display: block;
  width: 100%;
  margin-top: 5px;
}
.check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  max-width: 76ch;
  margin: 16px 0;
  font-weight: 500;
}
.check input {
  flex: none;
  width: 18px;
  min-height: 18px;
  margin: 2px 0 0;
  accent-color: var(--graphite);
}
.warning {
  padding: 10px 14px;
  border-radius: 6px;
  background: var(--amber-wash);
  color: var(--amber-ink);
}

/* Compact rows used across Advanced: name, one line of fact, then actions. */
.record {
  padding: 10px 0;
  border-top: 1px solid var(--line-soft);
  overflow-wrap: anywhere;
}
.record h3 {
  margin-bottom: 2px;
}
.record p {
  margin: 0 0 6px;
  color: var(--muted);
  font-size: 0.8125rem;
}
.record button {
  margin: 2px 4px 2px 0;
  font-size: 0.8125rem;
}

/* Overview */
.stored {
  margin-top: 16px;
}
.stored-line {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  margin: 0;
  max-width: none;
  font-size: 0.875rem;
}
.stored-line strong {
  font-weight: 700;
}
.model-note {
  margin: 8px 0 0;
}
.cell-message {
  overflow-wrap: anywhere;
}
.attention-table .cell-subject {
  white-space: nowrap;
}
.attention-table td:last-child,
.events-table td:last-child {
  width: 1%;
  white-space: nowrap;
}

/* Activity: the list and the event sit side by side, so reading one event never
   loses your place in fifty. */
#search {
  margin-bottom: 12px;
}
.activity-layout {
  display: grid;
  gap: 16px;
}
.activity-layout:has(#event-detail:not([hidden])) {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: start;
}
.activity-list {
  min-width: 0;
}
/* With the pane open the source column is the first thing to give way. */
.activity-layout:has(#event-detail:not([hidden])) .cell-source,
.activity-layout:has(#event-detail:not([hidden])) th:nth-child(2) {
  display: none;
}
.cell-source {
  color: var(--muted);
  font-size: 0.8125rem;
  white-space: nowrap;
}
.cell-event .cell-subject {
  display: block;
}
.cell-event .cell-message {
  display: block;
  margin-top: 1px;
  /* Two lines keep fifty rows scannable; the detail pane has the whole message. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  font-size: 0.8125rem;
}
.pager {
  justify-content: space-between;
  margin-top: 10px;
  color: var(--muted);
  font-size: 0.875rem;
}
#event-detail {
  position: sticky;
  top: 12px;
  min-width: 0;
  max-height: calc(100vh - 24px);
  overflow: auto;
  scrollbar-color: var(--dark-lamp) var(--surface);
}
#event-detail:focus {
  outline: none;
}
.detail-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px 16px;
}
#event-detail h3,
#review-evidence h3 {
  margin: 16px 0 6px;
}
#event-detail > .help {
  margin: 2px 0 14px;
}
.detail-message {
  max-width: none;
  margin: 14px 0 0;
  padding: 10px 12px;
  border-radius: 6px;
  background: var(--ground);
  font-size: 0.875rem;
  overflow-wrap: anywhere;
}
#event-detail .track-line,
#review-evidence .track-line {
  margin-top: 12px;
}
#event-detail pre {
  margin-bottom: 8px;
}

/* Review */
.section-first {
  margin-top: 0;
}
.review-open {
  margin: 12px 0 18px;
  font-size: 0.875rem;
}
.review-open label {
  margin: 0;
}
.review-open input {
  max-width: 340px;
}
.review-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  align-items: start;
  gap: 16px;
}
#review-evidence:focus {
  outline: none;
}
#review-evidence:empty {
  display: none;
}
#review-evidence .panel > p:last-child {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 0.8125rem;
}
#review-form h2 {
  margin-bottom: 8px;
}
.evaluate p {
  font-size: 0.875rem;
}
#evaluations {
  margin-top: 10px;
}

/* Configure. The toolbar turns violet only while a draft exists, so "this is not
   running yet" is impossible to miss and means exactly one thing. */
.config-actions {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 16px;
  min-height: 52px;
  margin-bottom: 16px;
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}
.config-actions.is-draft {
  border-color: var(--draft);
  background: var(--draft-wash);
}
.config-status {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.config-status p {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 600;
}
[data-page="configure"] input,
[data-page="configure"] select,
[data-page="configure"] button,
[data-page="configure"] legend {
  scroll-margin-top: 90px;
}
.monitor-tools {
  margin-bottom: 12px;
}
#active-monitors {
  display: grid;
  gap: 8px;
}
.monitor-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px 20px;
}
.monitor-status {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 0.875rem;
}
.monitor-facts {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 12px 20px;
  margin: 12px 0 8px;
}
.monitor-facts dt {
  color: var(--muted);
  font-size: 0.8125rem;
}
.monitor-facts dd {
  margin: 1px 0 0;
  font-size: 0.875rem;
  overflow-wrap: anywhere;
}
.monitor-record .help {
  margin: 4px 0 0;
}
#current-config > .help {
  margin-top: 12px;
}

/* Guide */
#setup-intro {
  max-width: 72ch;
}
.setup-steps {
  max-width: 760px;
  margin: 8px 0 24px;
}
.setup-steps .stage[aria-current="step"] strong {
  font-weight: 750;
}
.setup-steps .stage:not([aria-current="step"]) strong {
  color: var(--muted);
  font-weight: 500;
}
#setup-form fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
#setup-form [data-setup-step="0"],
#setup-form [data-setup-step="1"],
#setup-form [data-setup-step="2"] {
  max-width: 760px;
}
#setup-form legend {
  margin-bottom: 8px;
  padding: 0;
  font-size: 1.2rem;
  font-weight: 650;
}
#setup-form legend:focus {
  outline: none;
}
#setup-form .row {
  margin-top: 20px;
}
#setup-new-connection,
#setup-discord {
  margin-top: 14px;
  padding: 2px 16px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}
#setup-credential-optional {
  font-weight: 400;
}
#setup-connection-info {
  margin-top: 8px;
  overflow-wrap: anywhere;
}
.setup-review {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 12px;
}
.setup-review > * {
  min-width: 0;
}
.setup-summary {
  display: grid;
  grid-template-columns: 110px minmax(0, 1fr);
  gap: 6px 16px;
  margin: 0 0 12px;
  font-size: 0.875rem;
}
.setup-summary dt {
  color: var(--muted);
}
.setup-summary dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.setup-test {
  padding: 14px 18px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}
.setup-test h2 {
  margin-bottom: 6px;
  font-size: 1rem;
}
.setup-test p {
  font-size: 0.875rem;
}
#setup-test-result {
  margin-top: 12px;
  overflow-wrap: anywhere;
}
#setup-test-result p {
  margin-bottom: 4px;
}
#setup-status:not(:empty) {
  margin-top: 12px;
  padding: 10px 14px;
  border-radius: 6px;
  background: var(--amber-wash);
  color: var(--amber-ink);
}
#setup-open-advanced {
  margin-top: 16px;
}

/* Advanced: the editor is the work, and what it refers to sits alongside. */
.advanced-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(320px, 1fr);
  align-items: start;
  gap: 16px;
}
.advanced-editor {
  min-width: 0;
}
.editor-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 6px;
}
.editor-head label {
  margin: 0;
}
.advanced-editor > .help {
  margin: 8px 0;
}
#validation:not(:empty) {
  margin-top: 8px;
  font-size: 0.875rem;
}
#diff-content:empty {
  display: none;
}
.advanced-side {
  display: grid;
  gap: 12px;
  min-width: 0;
}
.side-group {
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}
.side-group h2 {
  margin: 0 0 8px;
  font-size: 1rem;
}
.side-group .help,
.side-group p {
  font-size: 0.8125rem;
}
.side-group select {
  width: 100%;
}
#model-form,
#source-form,
#policy-form {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line-soft);
}

/* Runtime */
.gate-state {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}
.gate-state .lamp {
  width: 18px;
  height: 18px;
  border-width: 3px;
}
.section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 24px 0 8px;
}

@media (max-width: 1099px) {
  /* Stacked, the open event comes first: it is what the operator just asked for. */
  .activity-layout:has(#event-detail:not([hidden])) {
    grid-template-columns: minmax(0, 1fr);
  }
  #event-detail {
    position: static;
    order: -1;
    max-height: none;
  }
  .advanced-layout,
  .review-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}
