  }
  .setup-summary {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }
  .setup-summary dd {
    margin-bottom: 8px;
  }
  .row > * {
    min-width: 0;
  }
  .row input {
    min-width: 100%;
  }
  .config-actions .row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 100%;
  }
  .monitor-head > .row {
    width: 100%;
  }
  .setup-steps {
    margin-bottom: 18px;
